import{_ as e,c as i,o as n,a4 as t}from"./chunks/framework.ttppV29E.js";const o="/assets/office-365-mail-create.BGq_9GKt.png",a="/assets/office-365-mail-use.BtWVOjOe.png",_=JSON.parse('{"title":"Office 365 Mail","description":"","frontmatter":{},"headers":[],"relativePath":"docs/connections/office-365-mail.md","filePath":"docs/connections/office-365-mail.md","lastUpdated":1782376534000}'),r={name:"docs/connections/office-365-mail.md"},s=t('<h1 id="office-365-mail" tabindex="-1">Office 365 Mail <a class="header-anchor" href="#office-365-mail" aria-label="Permalink to &quot;Office 365 Mail&quot;">​</a></h1><p>The Office 365 Mail connection stores the details required to send emails from your configured mailbox. This centralised configuration, can then be referenced by many Email Tasks across many endpoints.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>You will need the following pieces of information before you can create an Office 365 connection.</p><ul><li>An Azure Tenant ID.</li><li>An Entra Application ID.</li><li>Client Secret for the application (Registered as a secret within AireGlu&#39;s secrets).</li></ul><p>If you are wanting to connect to NHS Mail, please follow the process as documented here: <a href="https://support.nhs.net/knowledge-base/organisations-with-in-house-or-third-party-backend-applications-admin-guide/" target="_blank" rel="noreferrer">NHS Mail Application Request</a>.</p><p>Noting we currently only support client secrets and the required permission is <code>Graph Mail Application: Mail.Send</code></p><p>If you wish to configure an application within your own Azure Tenant please follow this guide: <a href="https://learn.microsoft.com/en-us/entra/identity-platform/quickstart-register-app" target="_blank" rel="noreferrer">Entra Quick Start Register App</a>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>When registering your own application it is your responsibility to configure the application correctly and to only give it access to the expected mailbox it should send emails from. Please see <a href="https://learn.microsoft.com/en-us/exchange/permissions-exo/application-rbac" target="_blank" rel="noreferrer">Exchange application rbac</a></p></div><h2 id="creating-an-office-365-mail-connection" tabindex="-1">Creating an Office 365 Mail Connection <a class="header-anchor" href="#creating-an-office-365-mail-connection" aria-label="Permalink to &quot;Creating an Office 365 Mail Connection&quot;">​</a></h2><p>Ensure you have the prerequisite information in hand and the Client Secret stored in AireGlu&#39;s secrets.</p><p>To add a new Client Connection:</p><ol><li>Go to the <strong>Connections</strong> section in AireGlu.</li><li>Click the <strong>Add</strong> button.</li><li>Select <strong>Office 365 Mail</strong> as the connection you want to create</li><li>Fill in the required fields: <ul><li><strong>Key</strong>: A unique identifier for this connection (e.g., <code>my-office-connection</code>).</li><li><strong>Display Name</strong>: A friendly name for easy reference.</li><li><strong>Azure Tenant ID</strong>: The Azure Tenant ID the app is registered under.</li><li><strong>Application ID</strong>: The registered Entra Application ID.</li><li><strong>Sender Email</strong>: The email address that should be used to send emails from.</li><li><strong>Client Secret</strong>: Reference an AireGlu secret that contains the client secret value.</li></ul></li><li>Click <strong>Save connection</strong>.</li></ol><p><img src="'+o+'" alt="Create Client Connection"></p><h2 id="using-an-office-365-mail-connection-in-email-tasks" tabindex="-1">Using an Office 365 Mail Connection in Email Tasks <a class="header-anchor" href="#using-an-office-365-mail-connection-in-email-tasks" aria-label="Permalink to &quot;Using an Office 365 Mail Connection in Email Tasks&quot;">​</a></h2><p>Once you have created an Office 365 Mail Connection, you can use it to send emails in your endpoint email tasks:</p><ol><li>In your endpoint, add or edit an <strong>Email Task</strong>.</li><li>Go to the <strong>Authorisation</strong> tab.</li><li>Set <strong>Type</strong> to <strong>Connection</strong>.</li><li>Search and select the desired <strong>Office 365 Mail Connection</strong>.</li></ol><p>When the task runs, AireGlu will automatically:</p><ul><li>Connect to your Entra Application using OAuth 2.0</li><li>Send the configured email details from the task from the configured sender email account.</li><li>And in the event of an authentication failure, the task will log the error details in the metrics under the &quot;Usage Data&quot; tab, allowing you to troubleshoot issues with your connection configuration.</li></ul><p><img src="'+a+'" alt="Use Office 365 Mail Connection in Email Task"></p>',20),l=[s];function c(f,u,p,d,h,g){return n(),i("div",null,l)}const y=e(r,[["render",c]]);export{_ as __pageData,y as default};
